import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useInView } from 'react-intersection-observer';
import { FaGithub, FaLinkedin, FaEnvelope } from 'react-icons/fa';
import emailjs from '@emailjs/browser';

const Contact = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: '',
  });
  const [ref, inView] = useInView({
    triggerOnce: false,
    threshold: 0.1,
  });

  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      // EmailJS configuration
      const serviceId = process.env.REACT_APP_EMAILJS_SERVICE_ID;
      const templateId = process.env.REACT_APP_EMAILJS_TEMPLATE_ID;
      const publicKey = process.env.REACT_APP_EMAILJS_PUBLIC_KEY;

      console.log('EmailJS Config:', { serviceId, templateId, publicKey });
      console.log('Form data:', formData);

      // Check if EmailJS is configured
      if (!serviceId || !templateId || !publicKey) {
        console.warn('EmailJS not configured. Using demo mode.');
        await new Promise(resolve => setTimeout(resolve, 1000));
        console.log('Demo mode - Form data:', formData);
        alert("Demo mode: EmailJS not configured yet. Please set up your EmailJS credentials to receive real emails.");
      } else {
        console.log('Sending email with EmailJS...');

        // Initialize EmailJS first
        emailjs.init(publicKey);

        // Prepare template parameters
        const templateParams = {
          from_name: formData.name,
          from_email: formData.email,
          message: formData.message,
          to_name: 'Prasannaram R R',
        };

        console.log('Template params:', templateParams);

        // Send email using EmailJS
        const result = await emailjs.send(serviceId, templateId, templateParams);

        console.log('Email sent successfully:', result);
        alert("Thanks for your message! I'll get back to you soon.");
      }

      // Reset form
      setFormData({
        name: '',
        email: '',
        message: '',
      });
    } catch (error) {
      console.error('Detailed error:', error);
      console.error('Error message:', error.message);
      console.error('Error status:', error.status);
      console.error('Error text:', error.text);

      // More specific error handling
      if (error.status === 400) {
        alert("Invalid request. Please check your form data and try again.");
      } else if (error.status === 401) {
        alert("Authentication failed. Please contact the site owner.");
      } else if (error.status === 402) {
        alert("EmailJS quota exceeded. Please contact the site owner.");
      } else {
        alert("Sorry, there was an error sending your message. Please try again or contact me directly at prasannaram978@gmail.com");
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
        <motion.section
      id="contact" 
      ref={ref}
      className="section-padding bg-white dark:bg-black relative overflow-hidden transition-colors duration-300"
    >
      <div className="container mx-auto relative z-10">
        <motion.div className="text-center mb-16">
          <motion.h2 
            className="text-4xl md:text-5xl font-bold mb-6 text-gray-900 dark:text-white"
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: inView ? 1 : 0, y: inView ? 0 : 30 }}
            viewport={{ once: false, amount: 0.3 }}
            transition={{ duration: 0.8 }}
          >
            Let's Connect
          </motion.h2>
          <motion.div
            className="w-24 h-1 bg-gradient-to-r from-transparent via-blue-600 to-transparent mx-auto mb-8"
            initial={{ width: 0 }}
            whileInView={{ width: inView ? 96 : 0 }}
            viewport={{ once: false, amount: 0.3 }}
            transition={{ duration: 1, delay: 0.5 }}
          />
          <motion.p
            className="text-gray-700 dark:text-gray-300 text-lg max-w-2xl mx-auto"
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: inView ? 1 : 0, y: inView ? 0 : 20 }}
            viewport={{ once: false, amount: 0.3 }}
            transition={{ duration: 0.8, delay: 0.3 }}
          >
            Ready to collaborate on your next project? Let's discuss how we can work together 
            to bring your ideas to life.
          </motion.p>
        </motion.div>

        <div className="max-w-6xl mx-auto grid grid-cols-1 lg:grid-cols-2 gap-16">
          {/* Contact Information */}
          <motion.div
            ref={ref}
            initial={{ opacity: 0, x: -50 }}
            whileInView={{ 
              opacity: inView ? 1 : 0, 
              x: inView ? 0 : -50
            }}
            viewport={{ once: false, amount: 0.3 }}
            transition={{ 
              opacity: { duration: 0.6 },
              x: { duration: 0.6 }
            }}
            className="space-y-8"
          >
            <div className="bg-white dark:bg-gray-800/50 backdrop-blur-sm rounded-2xl p-8 border border-gray-200 dark:border-gray-600 shadow-lg">
              <h3 className="text-2xl font-bold text-gray-900 dark:text-white mb-8">Get In Touch</h3>

              <div className="space-y-6">
                <motion.div 
                  className="group flex items-start space-x-4 p-4 rounded-xl hover:bg-gray-50 dark:hover:bg-white/5 transition-all duration-300"
                  whileHover={{ scale: 1.02, x: 5 }}
                >
                  <motion.div 
                    className="text-gray-900 dark:text-white mt-1 p-3 bg-gray-100 dark:bg-gray-700 rounded-full group-hover:bg-gray-200 dark:group-hover:bg-gray-600 transition-colors"
                    whileHover={{ rotate: 360 }}
                    transition={{ duration: 0.3 }}
                  >
                    <FaEnvelope size={20} />
                  </motion.div>
                  <div>
                    <h4 className="font-semibold text-gray-900 dark:text-white mb-1">Email</h4>
                    <a 
                      href="mailto:prasannaram978@gmail.com" 
                      className="text-gray-600 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white transition-colors text-lg"
                    >
                      prasannaram978@gmail.com
                    </a>
                  </div>
                </motion.div>

                <motion.div
                  className="group flex items-start space-x-4 p-4 rounded-xl hover:bg-gray-50 dark:hover:bg-white/5 transition-all duration-300"
                  whileHover={{ scale: 1.02, x: 5 }}
                >
                  <motion.div
                    className="text-gray-900 dark:text-white mt-1 p-3 bg-gray-100 dark:bg-gray-700 rounded-full group-hover:bg-gray-200 dark:group-hover:bg-gray-600 transition-colors"
                    whileHover={{ rotate: 360 }}
                    transition={{ duration: 0.3 }}
                  >
                    <span className="font-semibold" aria-hidden="true">#</span>
                  </motion.div>
                  <div>
                    <h4 className="font-semibold text-gray-900 dark:text-white mb-1">Phone</h4>
                    <a href="tel:+918778557651" className="text-gray-600 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white transition-colors text-lg">
                      +91 8778557651
                    </a>
                  </div>
                </motion.div>

                <motion.div 
                  className="group flex items-start space-x-4 p-4 rounded-xl hover:bg-gray-50 dark:hover:bg-white/5 transition-all duration-300"
                  whileHover={{ scale: 1.02, x: 5 }}
                >
                  <motion.div 
                    className="text-gray-900 dark:text-white mt-1 p-3 bg-gray-100 dark:bg-gray-700 rounded-full group-hover:bg-gray-200 dark:group-hover:bg-gray-600 transition-colors"
                    whileHover={{ rotate: 360 }}
                    transition={{ duration: 0.3 }}
                  >
                    <FaLinkedin size={20} />
                  </motion.div>
                  <div>
                    <h4 className="font-semibold text-gray-900 dark:text-white mb-1">LinkedIn</h4>
                    <a 
                      href="https://www.linkedin.com/in/prasannaram-r-r-327b09249/" 
                      target="_blank" 
                      rel="noopener noreferrer"
                      className="text-gray-600 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white transition-colors"
                    >
                      Connect with me professionally
                    </a>
                  </div>
                </motion.div>

                <motion.div 
                  className="group flex items-start space-x-4 p-4 rounded-xl hover:bg-gray-50 dark:hover:bg-white/5 transition-all duration-300"
                  whileHover={{ scale: 1.02, x: 5 }}
                >
                  <motion.div 
                    className="text-gray-900 dark:text-white mt-1 p-3 bg-gray-100 dark:bg-gray-700 rounded-full group-hover:bg-gray-200 dark:group-hover:bg-gray-600 transition-colors"
                    whileHover={{ rotate: 360 }}
                    transition={{ duration: 0.3 }}
                  >
                    <FaGithub size={20} />
                  </motion.div>
                  <div>
                    <h4 className="font-semibold text-gray-900 dark:text-white mb-1">GitHub</h4>
                    <a 
                      href="https://github.com/Prasannaram2k4" 
                      target="_blank" 
                      rel="noopener noreferrer"
                      className="text-gray-600 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white transition-colors"
                    >
                      Check out my projects
                    </a>
                  </div>
                </motion.div>
              </div>
            </div>
          </motion.div>

          {/* Contact Form */}
          <motion.div
            initial={{ opacity: 0, x: 50 }}
            whileInView={{ 
              opacity: inView ? 1 : 0, 
              x: inView ? 0 : 50
            }}
            viewport={{ once: false, amount: 0.3 }}
            transition={{ 
              opacity: { duration: 0.6, delay: 0.1 },
              x: { duration: 0.6, delay: 0.1 }
            }}
          >
            <div className="bg-white dark:bg-gray-800/50 backdrop-blur-sm rounded-2xl p-8 border border-gray-200 dark:border-gray-600 shadow-lg">
              <h3 className="text-2xl font-bold text-gray-900 dark:text-white mb-8">Send a Message</h3>

              <form onSubmit={handleSubmit} className="space-y-6">
                <motion.div
                  whileFocus={{ scale: 1.01 }}
                  transition={{ duration: 0.2 }}
                >
                  <label htmlFor="name" className="block text-gray-900 dark:text-white mb-3 font-medium">Name</label>
                  <input
                    type="text"
                    id="name"
                    name="name"
                    value={formData.name}
                    onChange={handleChange}
                    className="w-full bg-white dark:bg-gray-900/50 text-gray-900 dark:text-white border border-gray-300 dark:border-gray-600 rounded-lg p-4 focus:outline-none focus:border-gray-900 dark:focus:border-white focus:bg-white dark:focus:bg-gray-800/50 transition-all duration-300 backdrop-blur-sm"
                    placeholder="Your name"
                    required
                  />
                </motion.div>

                <motion.div
                  whileFocus={{ scale: 1.01 }}
                  transition={{ duration: 0.2 }}
                >
                  <label htmlFor="email" className="block text-gray-900 dark:text-white mb-3 font-medium">Email</label>
                  <input
                    type="email"
                    id="email"
                    name="email"
                    value={formData.email}
                    onChange={handleChange}
                    className="w-full bg-white dark:bg-gray-900/50 text-gray-900 dark:text-white border border-gray-300 dark:border-gray-600 rounded-lg p-4 focus:outline-none focus:border-gray-900 dark:focus:border-white focus:bg-white dark:focus:bg-gray-800/50 transition-all duration-300 backdrop-blur-sm"
                    placeholder="your.email@example.com"
                    required
                  />
                </motion.div>

                <motion.div
                  whileFocus={{ scale: 1.01 }}
                  transition={{ duration: 0.2 }}
                >
                  <label htmlFor="message" className="block text-gray-900 dark:text-white mb-3 font-medium">Message</label>
                  <textarea
                    id="message"
                    name="message"
                    value={formData.message}
                    onChange={handleChange}
                    rows="6"
                    className="w-full bg-white dark:bg-gray-900/50 text-gray-900 dark:text-white border border-gray-300 dark:border-gray-600 rounded-lg p-4 focus:outline-none focus:border-gray-900 dark:focus:border-white focus:bg-white dark:focus:bg-gray-800/50 transition-all duration-300 backdrop-blur-sm resize-none"
                    placeholder="Tell me about your project or just say hello!"
                    required
                  ></textarea>
                </motion.div>

                <motion.button
                  type="submit"
                  disabled={isSubmitting}
                  className={`w-full py-4 px-6 rounded-lg font-semibold text-lg transition-all duration-300 ${
                    isSubmitting 
                      ? 'bg-gray-400 dark:bg-gray-600 text-gray-600 dark:text-gray-300 cursor-not-allowed' 
                      : 'bg-gray-900 dark:bg-white text-white dark:text-gray-900 hover:bg-gray-700 dark:hover:bg-gray-200 shadow-lg hover:shadow-xl'
                  }`}
                  whileHover={!isSubmitting ? { 
                    scale: 1.02,
                    boxShadow: "0 10px 30px rgba(0,0,0,0.1)"
                  } : {}}
                  whileTap={!isSubmitting ? { scale: 0.98 } : {}}
                >
                  {isSubmitting ? (
                    <div className="flex items-center justify-center">
                      <motion.div
                        className="w-5 h-5 border-2 border-gray-600 dark:border-gray-300 border-t-transparent rounded-full mr-3"
                        animate={{ rotate: 360 }}
                        transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
                      />
                      Sending...
                    </div>
                  ) : (
                    'Send Message'
                  )}
                </motion.button>
              </form>
            </div>
          </motion.div>
        </div>
      </div>
    </motion.section>
  );
};

export default Contact;
